def run_machine(program):
    st = []
    for ins in program:
        parts = ins.split()
        op = parts[0]
        if op == 'PUSH':
            st.append(int(parts[1]))
        elif op == 'ADD':
            a = st.pop(); b = st.pop(); st.append(a + b)
        elif op == 'SUBR':
            a = st.pop(); b = st.pop(); st.append(a - b)
        elif op == 'DUP':
            st.append(st[-1])
        elif op == 'SWAP':
            st[-1], st[-2] = st[-2], st[-1]
        elif op == 'TWIST':
            a = st.pop(); st.append(a * 3 + 1)
    return st[-1] if st else -1

