def count_paths(grid):
    R, C = len(grid), len(grid[0])
    dp = [[None] * C for _ in range(R)]
    for i in range(R):
        for j in range(C):
            cur = {}
            if i == 0 and j == 0:
                cur[grid[0][0] % 3] = 1
            else:
                for pi, pj in ((i - 1, j), (i, j - 1)):
                    if pi >= 0 and pj >= 0:
                        for rem, cnt in dp[pi][pj].items():
                            nr = (rem + grid[i][j]) % 3
                            cur[nr] = cur.get(nr, 0) + cnt
            dp[i][j] = cur
    return dp[R - 1][C - 1].get(0, 0)

